    'faq' => [
        ['q' => "Odoo est-il conforme au SYSCOHADA révisé ?", 'r' => "Odoo fournit une localisation OHADA avec le plan SYSCOHADA révisé et, depuis la version 18, un module par pays membre avec ses taxes et sa déclaration de TVA. La conformité de votre comptabilité dépend ensuite de votre paramétrage et de votre façon de saisir : c'est précisément ce que la formation vérifie et fait pratiquer."],
        ['q' => "Peut-on tenir la comptabilité SYSCOHADA avec Odoo Community ?", 'r' => "La page des éditions d'Odoo réserve la comptabilité complète (grand livre, rapprochement des relevés, rapports, localisations) à l'édition Enterprise ; Community propose la facturation et les paiements. Une comptabilité tenue sur Community repose donc sur des modules complémentaires, à examiner au cas par cas avant la formation."],
        ['q' => "Notre base a démarré avec un plan générique : peut-on changer de localisation ?", 'r' => "Selon la documentation d'Odoo, la localisation fiscale d'une société ne peut plus être modifiée dès qu'une écriture a été comptabilisée. La solution relève alors d'un projet de reprise, souvent une nouvelle société dans la base avec reprise des soldes, à cadrer avant toute formation."],
        ['q' => "Odoo produit-il les états financiers au format SYSCOHADA ?", 'r' => "Odoo produit un bilan, un compte de résultat, un tableau des flux de trésorerie, une balance générale et un grand livre, exportables en PDF et en Excel. Leur présentation se compare aux modèles du SYSCOHADA pendant la formation ; l'écart se comble par une table de passage, ou par un rapport personnalisé construit sur les préfixes de comptes, et les notes annexes se rédigent hors du logiciel."],
        ['q' => "Les retenues à la source sont-elles prévues ?", 'r' => "Le module du pays ne les livre pas toutes. La documentation d'Odoo décrit leur création comme des taxes à montant négatif, rattachées à un groupe de retenue. Les taux et les cas d'application sont validés par votre conseil fiscal ; la formation montre comment les paramétrer et les contrôler dans la déclaration."],
        ['q' => "Comment traiter les encaissements Mobile Money ?", 'r' => "Chaque portefeuille d'opérateur reçoit son journal et son compte de trésorerie. Quand l'opérateur fournit un relevé en CSV ou en Excel, il s'importe après correspondance des colonnes ; sinon, les opérations se saisissent. Le rapprochement lettre chaque encaissement avec sa facture et isole les commissions grâce à un modèle de rapprochement."],
        ['q' => "Une association peut-elle suivre cette formation ?", 'r' => "Oui. Les entités à but non lucratif relèvent d'un Acte uniforme spécifique, en vigueur depuis le 1er janvier 2024, et Odoo propose un plan SYCEBNL dans sa localisation OHADA. La formation s'appuie alors sur ce plan et sur la comptabilité analytique pour suivre chaque financement."],
        ['q' => "Notre entreprise relève du système minimal de trésorerie : Odoo convient-il ?", 'r' => "Odoo tient une comptabilité d'engagement, plus complète que la comptabilité de trésorerie du système minimal. Il reste utilisable, mais la formation commence par vérifier que ce choix est justifié ; une petite entité peut parfois se contenter d'un outil plus simple."],
        ['q' => "Faut-il être comptable pour suivre la formation ?", 'r' => "Oui, il faut connaître la comptabilité générale et le plan SYSCOHADA. La formation enseigne la tenue de ce référentiel dans Odoo, pas la comptabilité elle-même. Les personnes qui produisent les factures sans passer d'écritures ont leur propre formation, par poste."],
        ['q' => "Combien de personnes par groupe ?", 'r' => "De 2 à 5 comptables. Chaque participant saisit et contrôle sur son poste, et le formateur reprend les écritures qui ne concordent pas. Au-delà de cinq, ce suivi individuel n'est plus possible."],
        ['q' => "La formation peut-elle se faire à distance ?", 'r' => "Oui, en séances de deux à trois heures avec partage d'écran et prise en main de votre copie de base. Un second écran par participant est conseillé. Pour une première mise en place, le diagnostic sur place ou la formule mixte reste préférable."],
        ['q' => "Nos données comptables restent-elles confidentielles ?", 'r' => "Oui. Les accès sont nominatifs et limités à la durée de la mission, la copie de formation est supprimée à la fin, et un engagement de confidentialité peut être signé avant le diagnostic. Aucune pièce vue chez une entreprise ne sert d'exemple ailleurs."],
        ['q' => "Combien coûte la formation ?", 'r' => "Le prix est fixé sur devis, après un cadrage gratuit. Il dépend du nombre de sociétés, de l'état du paramétrage, de la reprise des soldes et du lieu. Les abonnements à Odoo et l'hébergement restent dus à l'éditeur ou à votre hébergeur."],
    ],

